/bin/bash -lc "python3 - <<'PY'
import cv2, numpy as np
from PIL import Image
im=np.array(Image.open('first_frame.png')); gray=cv2.cvtColor(im,cv2.COLOR_RGB2GRAY)
for th in [15,25,40,55,70,85,100]:
 m=(gray<th).astype(np.uint8)
 n,L,st,cen=cv2.connectedComponentsWithStats(m,8)
 print('\\nTH',th,'coverage',m.sum())
 for i in np.argsort(st[1:,4])[::-1][:20]+1:
  x,y,w,h,a=st[i];
  if a>=8: print((x,y,w,h,a), np.round(cen[i],1))
# color saturation components
hsv=cv2.cvtColor(im,cv2.COLOR_RGB2HSV)
for cond,name in [((hsv[:,:,1]>80)&(hsv[:,:,2]<130),'satdark'),((im[:,:,0]>im[:,:,1]*1.15)&(im[:,:,0]>im[:,:,2]*1.25),'reddish')]:
 m=cond.astype(np.uint8); n,L,st,cen=cv2.connectedComponentsWithStats(m,8); print(name,m.sum())
 for i in np.argsort(st[1:,4])[::-1][:15]+1:
  x,y,w,h,a=st[i];
  if a>10: print((x,y,w,h,a),np.round(cen[i],1), np.round(im[L==i].mean(0),1))
# coarse mean RGB each 16x16
print('\\n16 grid grayscale mean')
for y in range(0,144,8): print(y,' '.join(f'{gray[y:y+8,x:x+8].mean():3.0f}' for x in range(0,256,8)))
PY"
